import { motion, useInView } from "framer-motion";
import { useRef } from "react";
import { Briefcase, GraduationCap } from "lucide-react";

const experiences = [
  {
    type: "work",
    title: "Web Development Intern",
    company: "Tech Company",
    period: "Jan 2025 - May 2025",
    description: "Developed responsive web applications using React and improved site performance by 40%."
  },
  {
    type: "education",
    title: "Master of Computer Applications",
    company: "University Name",
    period: "2023 - 2025",
    description: "CGPA: 8.5/10. Specialized in Software Engineering and Web Technologies."
  },
  {
    type: "education",
    title: "Bachelor of Computer Applications",
    company: "College Name",
    period: "2020 - 2023",
    description: "CGPA: 8.0/10. Foundation in programming, databases, and networking."
  }
];

const Experience = () => {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true });

  return (
    <section id="experience" className="experience-section" ref={ref}>
      <motion.h2
        initial={{ opacity: 0, y: 30 }}
        animate={isInView ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.6 }}
      >
        Experience & Education
      </motion.h2>

      <div className="timeline">
        {experiences.map((exp, index) => (
          <motion.div
            key={index}
            initial={{ opacity: 0, x: index % 2 === 0 ? -50 : 50 }}
            animate={isInView ? { opacity: 1, x: 0 } : {}}
            transition={{ duration: 0.6, delay: index * 0.2 }}
            className={`timeline-item ${exp.type}`}
          >
            <div className="timeline-icon">
              {exp.type === "work" ? <Briefcase /> : <GraduationCap />}
            </div>
            <div className="timeline-content">
              <h3>{exp.title}</h3>
              <h4>{exp.company}</h4>
              <span className="period">{exp.period}</span>
              <p>{exp.description}</p>
            </div>
          </motion.div>
        ))}
      </div>
    </section>
  );
};

export default Experience;
